<script lang="ts">import {onMount} from 'svelte';import type {MapInfo} from './server/data';let{title,items,showStarted=false}:{title:string;items:MapInfo[];showStarted?:boolean}=$props();let target:HTMLElement;onMount(()=>{void init();});async function init(){const L=await import('leaflet');const map=L.map(target,{scrollWheelZoom:false}).setView([51.0447,-114.0719],10);L.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{attribution:'&copy; OpenStreetMap contributors'}).addTo(map);const bounds:[number,number][]=[];for(const item of items){const point:[number,number]=[item.latitude,item.longitude];bounds.push(point);L.marker(point).addTo(map).bindPopup(`<strong>${item.location}</strong><br>${item.description}${showStarted?`<br>Started: ${new Date(item.created).toLocaleString()}`:''}`)}if(bounds.length)map.fitBounds(bounds,{padding:[30,30],maxZoom:13})}</script>
<div><h3 class="text-center">{title}</h3><div class="map-shell"><div bind:this={target} class="leaflet-map" data-testid="leaflet-map" aria-label={title}></div>{#if !items.length}<p class="map-message">No current items reported.</p>{/if}</div></div>
